import "github.com/mattn/anko/ast"

// scanDefaults removes default expressions from the token stream seen by the
// generated parser, while parsing the expressions with the same parser.
func (l *Lexer) scanDefaults(pos ast.Position) {
 s := *l.s
 tok, _, _, err := s.Scan()
 if tok == IDENT { tok, _, _, err = s.Scan() }
 if err != nil || tok != '(' { return }
 var defaults []ast.Expr
 type span struct { start, end int }
 var spans []span
 seenDefault := false
 for {
  tok, _, _, err = s.Scan()
  if err != nil || tok == EOF { return }
  if tok == ')' { break }
  if tok != IDENT { return }
  tok, _, p, err := s.Scan()
  if err != nil { return }
  var def ast.Expr
  if tok == '=' {
   start := s.offset
   depth := 0
   end := start
   for {
    s.skipBlank()
    end = s.offset
    tok, _, p, err = s.Scan()
    if err != nil || tok == EOF { return }
    if depth == 0 && (tok == ',' || tok == ')' || tok == VARARG) { break }
    switch tok { case '(', '[', '{': depth++; case ')', ']', '}': depth-- }
    if depth < 0 { return }
   }
   if tok == VARARG {
    l.e = &Error{Message: "invalid default argument declaration", Pos: p}
    return
   }
   stmt, parseErr := ParseSrc("return " + string(s.src[start:end]))
   if parseErr != nil { l.e = parseErr; return }
   stmts, ok := stmt.(*ast.StmtsStmt)
   if !ok || len(stmts.Stmts) != 1 { l.e = &Error{Message: "syntax error", Pos: p}; return }
   ret, ok := stmts.Stmts[0].(*ast.ReturnStmt)
   if !ok || len(ret.Exprs) != 1 { l.e = &Error{Message: "syntax error", Pos: p}; return }
