s=open(p).read(); start=s.index('  // Build provider request\n',s.index('async function* executeSingleAgent')); end=s.index('\n}\n',start)
s=s[:start]+'''  const result = yield* runAgent(agentId, request, abortController, debugMode, []);
  if (result.error) yield { type: "error", error: result.error };
  else if (!abortController.signal.aborted) yield { type: "done" };
