/** Execute one agent, preserving its conversation across tool calls. */
async function* runAgent(
  agentId: string,
  request: ChatRequest,
  abortController: AbortController,
  debugMode: boolean,
  ancestry: string[]
): AsyncGenerator<StreamResponse, { text: string; error?: string }> {
  const provider = globalRegistry.getProviderForAgent(agentId);
  const agent = globalRegistry.getAgent(agentId);
  if (!provider || !agent) return { text: "", error: `Agent '${agentId}' not found or provider not available` };

  const context: ProviderContext[] = [{ role: "user", content: request.message }];
  let totalText = "";
  const path = [...ancestry, agentId];
  // Bound repeated tool calls even when no cycle occurs.
  for (let turn = 0; turn < 32; turn++) {
    if (abortController.signal.aborted) return { text: totalText, error: "Request aborted" };
    const calls: Array<{ id: string; name: string; input: unknown }> = [];
    const blocks: Array<Record<string, unknown>> = [];
    const providerRequest: ProviderChatRequest = {
      message: turn === 0 ? request.message : "",
      sessionId: request.sessionId,
      requestId: request.requestId,
      workingDirectory: request.workingDirectory || agent.workingDirectory,
      ...(turn ? { context: [...context] } : {}),
    };
    try {
      for await (const response of provider.executeChat(providerRequest, {
        debugMode, abortController, temperature: agent.config?.temperature, maxTokens: agent.config?.maxTokens,
      })) {
        if (abortController.signal.aborted) return { text: totalText, error: "Request aborted" };
        if (response.type === "error") return { text: totalText, error: response.error || "Agent failed" };
        if (response.type === "text") {
          const text = response.content || "";
          totalText += text;
          const last = blocks[blocks.length - 1];
          if (last?.type === "text") last.text = String(last.text) + text;
          else blocks.push({ type: "text", text });
        }
        if (response.type === "tool_use" && response.toolName === "delegate_task") {
          const id = response.toolUseId || `delegate-${turn}-${calls.length}`;
          calls.push({ id, name: response.toolName, input: response.toolInput });
          blocks.push({ type: "tool_use", id, name: response.toolName, input: response.toolInput });
          yield { type: "claude_json", data: { type: "tool_use", id, name: response.toolName, input: response.toolInput } };
          continue;
        }
        const message = createChatRoomMessage(response, agentId);
        if (message) yield { type: "claude_json", data: { type: "chat_room_message", message, session_id: request.sessionId } };
        if (response.type === "text") yield { type: "claude_json", data: { type: "assistant", content: response.content, model: response.metadata?.model } };
      }
    } catch (error) {
      return { text: totalText, error: error instanceof Error ? error.message : String(error) };
    }
    if (!calls.length) return { text: totalText };
    context.push({ role: "assistant", content: JSON.stringify(blocks) });
    const results: Array<Record<string, unknown>> = [];
    for (const call of calls) {
      const input = call.input as { agent_id?: unknown; instructions?: unknown } | null;
      const target = typeof input?.agent_id === "string" ? input.agent_id : "";
      const instructions = typeof input?.instructions === "string" ? input.instructions : "";
      let result: { text: string; error?: string };
      if (!target || !instructions) {
        result = { text: "", error: `Invalid delegation input for agent '${target}'` };
      } else if (path.includes(target)) {
        result = { text: "", error: `Circular delegation detected: ${[...path, target].join(" -> ")}` };
        yield { type: "error", error: result.error };
      } else if (!globalRegistry.getAgent(target) || !globalRegistry.getProviderForAgent(target)) {
        result = { text: "", error: `Agent '${target}' not found or provider not available` };
        yield { type: "error", error: result.error };
      } else {
        result = yield* runAgent(target, { message: instructions, requestId: request.requestId }, abortController, debugMode, path);
