import {IgnoreTypes} from '../utils/ignore-types';
import RuleBuilder, {BooleanOptionBuilder, DropdownOptionBuilder, ExampleBuilder, NumberOptionBuilder, OptionBuilderBase, TextAreaOptionBuilder, TextOptionBuilder} from './rule-builder';
import {generateToc} from '../utils/toc';

class AutoTocOptions implements Options {
  listStyle?: 'bullet' | 'number' = 'bullet';
  bulletMarker?: string = '-';
  orderedListStyle?: 'always-one' | 'increment' = 'always-one';
  indentSize?: number = 2;
  minLevel?: number = 2;
  maxLevel?: number = 6;
  title?: string = '';
  useExplicitIds?: boolean = false;
  stripFormattingInToc?: boolean = false;
  excludeHeadings?: string[] = [];
}

@RuleBuilder.register
export default class AutoToc extends RuleBuilder<AutoTocOptions> {
  constructor() {
    super({nameKey: 'rules.auto-toc.name', descriptionKey: 'rules.auto-toc.description', type: RuleType.CONTENT,
      ruleIgnoreTypes: [IgnoreTypes.yaml, IgnoreTypes.code, IgnoreTypes.math]});
  }
  get OptionsClass(): new () => AutoTocOptions { return AutoTocOptions; }
  apply(text: string, options: AutoTocOptions): string { return generateToc(text, options); }
  get exampleBuilders(): ExampleBuilder<AutoTocOptions>[] {
    return [new ExampleBuilder({description: 'Generate a table of contents.', before: '<!-- toc -->\n\n## Heading', after: '<!-- toc -->\n\n- [Heading](#heading)\n\n<!-- /toc -->\n\n## Heading'})];
  }
  get optionBuilders(): OptionBuilderBase<AutoTocOptions>[] {
    return [
      new DropdownOptionBuilder({OptionsClass: AutoTocOptions, nameKey: 'rules.auto-toc.list-style.name', descriptionKey: 'rules.auto-toc.list-style.description', optionsKey: 'listStyle', records: [{value: 'bullet', description: 'bullet'}, {value: 'number', description: 'number'}]}),
      new TextOptionBuilder({OptionsClass: AutoTocOptions, nameKey: 'rules.auto-toc.bullet-marker.name', descriptionKey: 'rules.auto-toc.bullet-marker.description', optionsKey: 'bulletMarker'}),
      new DropdownOptionBuilder({OptionsClass: AutoTocOptions, nameKey: 'rules.auto-toc.ordered-list-style.name', descriptionKey: 'rules.auto-toc.ordered-list-style.description', optionsKey: 'orderedListStyle', records: [{value: 'always-one', description: 'always-one'}, {value: 'increment', description: 'increment'}]}),
      new NumberOptionBuilder({OptionsClass: AutoTocOptions, nameKey: 'rules.auto-toc.indent-size.name', descriptionKey: 'rules.auto-toc.indent-size.description', optionsKey: 'indentSize'}),
      new NumberOptionBuilder({OptionsClass: AutoTocOptions, nameKey: 'rules.auto-toc.min-level.name', descriptionKey: 'rules.auto-toc.min-level.description', optionsKey: 'minLevel'}),
      new NumberOptionBuilder({OptionsClass: AutoTocOptions, nameKey: 'rules.auto-toc.max-level.name', descriptionKey: 'rules.auto-toc.max-level.description', optionsKey: 'maxLevel'}),
      new TextOptionBuilder({OptionsClass: AutoTocOptions, nameKey: 'rules.auto-toc.title.name', descriptionKey: 'rules.auto-toc.title.description', optionsKey: 'title'}),
      new BooleanOptionBuilder({OptionsClass: AutoTocOptions, nameKey: 'rules.auto-toc.use-explicit-ids.name', descriptionKey: 'rules.auto-toc.use-explicit-ids.description', optionsKey: 'useExplicitIds'}),
      new BooleanOptionBuilder({OptionsClass: AutoTocOptions, nameKey: 'rules.auto-toc.strip-formatting-in-toc.name', descriptionKey: 'rules.auto-toc.strip-formatting-in-toc.description', optionsKey: 'stripFormattingInToc'}),
      new TextAreaOptionBuilder({OptionsClass: AutoTocOptions, nameKey: 'rules.auto-toc.exclude-headings.name', descriptionKey: 'rules.auto-toc.exclude-headings.description', optionsKey: 'excludeHeadings'}),
    ];
  }
}
"}

{"file_path": "/app/src/utils/toc.ts", "content": "import {Options} from '../rules';

/** Resolve links and remove images before using heading text in a TOC. */
function displayText(text: string): string {
  return text.replace(/!\[\[[^\]]*\]\]/g, '')
      .replace(/!\[[^\]]*\]\([^)]*\)/g, '')
      .replace(/\[\[([^\]]+)\]\]/g, (_match, target: string) => target.split('|').pop())
      .replace(/\[([^\]]+)\]\([^)]*\)/g, '$1');
}

function plainText(text: string): string {
  return displayText(text).replace(/<[^>]*>/g, '').replace(/[*_~`]/g, '').replace(/\\([\\`*_{}\[\]()#+.!-])/g, '$1');
}

export function generateToc(text: string, options: Options): string {
  const start = /<!--[ \t]*toc[ \t]*-->/i.exec(text);
  if (!start) return text;
  const startEnd = start.index + start[0].length;
  const end = /<!--[ \t]*\/toc[ \t]*-->/i.exec(text.slice(startEnd));
  const endStart = end ? startEnd + end.index : startEnd;
  const endEnd = end ? endStart + end[0].length : startEnd;
  const content = text.slice(0, start.index) + '\n' + text.slice(endEnd);
  const min = Math.max(1, Math.min(6, Number(options.minLevel) || 2));
  const max = Math.max(1, Math.min(6, Number(options.maxLevel) || 6));
  const indent = Math.max(0, Math.floor(Number(options.indentSize) || 0));
  const excluded = (options.excludeHeadings || []).map((item: string) => {
    if (item.startsWith('/') && item.endsWith('/') && item.length > 1) {
      try { return new RegExp(item.slice(1, -1), 'i'); } catch (_) { /* Treat invalid expressions as literals. */ }
    }
    return item.toLowerCase();
  });
  const used = new Set<string>();
  const items: string[] = [];
  for (const line of content.split(/\r?\n/)) {
    const match = /^ {0,3}(#{1,6})(?:[ \t]+|$)(.*)$/.exec(line);
    if (!match) continue;
    const level = match[1].length;
    if (level < min || level > max) continue;
    let heading = match[2].replace(/[ \t]+#+[ \t]*$/, '').trim();
    const id = /[ \t]+\{#([^\s}]+)\}[ \t]*$/.exec(heading);
    if (id) heading = heading.slice(0, id.index).trim();
    const label = displayText(heading).trim();
    const plain = plainText(heading).trim();
    if (excluded.some((entry: string | RegExp) => typeof entry === 'string' ? entry === plain.toLowerCase() : entry.test(plain))) continue;
    const base = options.useExplicitIds && id ? id[1] : plain.toLowerCase().replace(/\s+/g, '-').replace(/[^a-z0-9_-]/g, '').replace(/-+/g, '-').replace(/^-|-$/g, '');
    let anchor = base;
    let suffix = 1;
    while (used.has(anchor)) anchor = `${base}-${suffix++}`;
    used.add(anchor);
    const marker = options.listStyle === 'number' ? `${options.orderedListStyle === 'increment' ? items.length + 1 : 1}.` : options.bulletMarker;
    items.push(`${' '.repeat((level - min) * indent)}${marker} [${options.stripFormattingInToc ? plain : label}](#${anchor})`);
  }
  const newline = text.includes('\r\n') ? '\r\n' : '\n';
  const body = [options.title, items.join(newline)].filter(Boolean).join(newline + newline);
  const before = text.slice(0, startEnd);
  const after = text.slice(endEnd).replace(/^(?:[ \t]*\r?\n)*/, '');
  return before + newline + newline + (body ? body + newline + newline : '') + (end ? end[0] : '<!-- /toc -->') + newline + newline + after;
}
"}

{"file_path": "/app/src/core/atomicSelectors.ts", "content": "import { Logic, Selector } from '../types'

type Read = { name: string; value: any; get: (root: any) => any }
type Node = {
  name: string
  args: Selector[]
  inputs: (string | undefined)[]
  compute: (...args: any[]) => any
  reads: Read[]
  values: any[]
  result: any
  initialized: boolean
  evaluations: number
  dirtyCause: string | null
}

/** Per-built-logic selector graph. It does not subscribe to the store or alter lifecycle hooks. */
export class AtomicSelectors {
  private nodes: Record<string, Node> = {}
  private names = new WeakMap<Selector, string>()
  private order: string[] = []
  private running = new Set<string>()

  constructor(private logic: Logic) {}

  register(name: string, selector: Selector): void {
    this.names.set(selector, name)
  }

  add(name: string, args: Selector[], compute: (...args: any[]) => any): Selector {
    const node: Node = {
      name, args, compute, inputs: args.map((arg) => this.names.get(arg)), reads: [], values: [],
      result: undefined, initialized: false, evaluations: 0, dirtyCause: null,
    }
    this.nodes[name] = node
    return (state, props) => this.evaluate(node, state, props)
  }

  validate(): void {
    const visiting = new Set<string>()
    const visited = new Set<string>()
    const order: string[] = []
    const visit = (name: string) => {
      if (visiting.has(name)) throw new Error('[KEA] Circular dependency detected')
      if (visited.has(name)) return
      visiting.add(name)
      for (const input of this.nodes[name].inputs) if (input && this.nodes[input]) visit(input)
      visiting.delete(name)
      visited.add(name)
      order.push(name)
    }
    for (const name of Object.keys(this.nodes)) visit(name)
    this.order = order
  }

  health() {
    const selectors: Record<string, { dependencies: string[]; dependents: string[]; evaluations: number; dirtyCause: string | null }> = {}
    for (const name of Object.keys(this.nodes)) {
      const node = this.nodes[name]
      selectors[name] = {
        dependencies: Array.from(new Set([...node.inputs.filter((input): input is string => !!input && !!this.nodes[input]), ...node.reads.map((read) => read.name)])),
        dependents: Object.keys(this.nodes).filter((other) => this.nodes[other].inputs.includes(name)),
        evaluations: node.evaluations,
        dirtyCause: node.dirtyCause,
      }
    }
    return { selectors, topologicalOrder: this.order.slice() }
  }

  private evaluate(node: Node, state: any, props: any): any {
    if (this.running.has(node.name)) throw new Error('[KEA] Circular dependency detected')
    this.running.add(node.name)
    try {
      const values = node.args.map((arg) => arg(state, props))
      let cause: string | null = null
      if (node.initialized) {
        for (let i = 0; i < values.length; i++) {
          const name = node.inputs[i]
          if (name && this.nodes[name] && !Object.is(values[i], node.values[i])) {
            cause = `selector:${name}`
            break
          }
          if (!name && !Object.is(values[i], node.values[i])) {
            cause = name ?? `input:${i}`
            break
          }
        }
        if (!cause) {
          for (const read of node.reads) {
            const index = Number((read as any).index)
            if (!Object.is(read.value, read.get(values[index]))) { cause = read.name; break }
          }
        }
        if (!cause) return node.result
      }
      const reads: Read[] = []
      const proxies = new WeakMap<object, any>()
      const originals = new WeakMap<object, any>()
      const tracked = values.map((value, index) => {
        const name = node.inputs[index]
        if (!name || this.nodes[name]) return value
        const record = (path: string, get: (root: any) => any) => {
          const read = { name: path, get, value: get(value), index }
          reads.push(read)
        }
        const wrap = (current: any, path: string, get: (root: any) => any): any => {
          if (current === null || typeof current !== 'object') { record(path, get); return current }
          if (proxies.has(current)) return proxies.get(current)
          const proxy = new Proxy(current, {
            get: (target, property, receiver) => {
              if (target instanceof Map && property === 'get') return (key: any) => {
                const next = (root: any) => get(root)?.get(key)
                return wrap(target.get(key), `${path}.map:${String(key)}`, next)
              }
              if (target instanceof Map && property === 'has') return (key: any) => {
                const next = (root: any) => get(root)?.has(key)
                record(`${path}.map:${String(key)}`, next)
                return target.has(key)
              }
              if (target instanceof Set && property === 'has') return (key: any) => {
                const next = (root: any) => get(root)?.has(key)
                record(`${path}.set:${String(key)}`, next)
                return target.has(key)
              }
              const result = Reflect.get(target, property, receiver)
              if (typeof result === 'function') {
                if (target instanceof Map || target instanceof Set) { record(path, get); return result.bind(target) }
                return result
              }
              if (typeof property === 'symbol') return result
              const next = (root: any) => get(root)?.[property]
              return wrap(result, `${path}.${String(property)}`, next)
            },
          })
          proxies.set(current, proxy)
          originals.set(proxy, current)
          return proxy
        }
        const wrapped = wrap(value, name, (root) => root)
        return wrapped
      })
      node.evaluations++
      let result = node.compute(...tracked)
      if (result && typeof result === 'object' && originals.has(result)) {
        result = originals.get(result)
        const index = tracked.indexOf(node.compute === undefined ? undefined : tracked.find((item) => item && originals.get(item) === result))
        if (index >= 0 && node.inputs[index]) {
          const get = (root: any) => root
          reads.push({ name: node.inputs[index]!, get, value: values[index], index } as Read)
        }
      }
      node.reads = reads
      node.values = values
      node.result = result
      node.initialized = true
      node.dirtyCause = cause
      return result
    } finally {
      this.running.delete(node.name)
    }
  }
}
"}

