    """Fit a raw-column contract before preprocessing."""
    if options is None:
        options = {}
    if not isinstance(options, dict):
        raise ValueError("dataset.features must be an object")
    targets = targets or []
    raw = [name for name in dataset.columns if name not in targets]

    def names(key):
        value = options.get(key)
        if value is None:
            return None
        if isinstance(value, str):
            value = [value]
        if not isinstance(value, list) or any(
            not isinstance(name, str) or not name.strip() for name in value
        ):
            raise ValueError(f"features.{key} must contain non-empty column names")
        if len(set(value)) != len(value):
            raise ValueError(f"features.{key} contains duplicate entries")
        invalid_targets = [name for name in value if name in targets]
        if invalid_targets:
            raise ValueError(f"features.{key} contains target columns: {invalid_targets}")
        unknown = [name for name in value if name not in raw]
        if unknown:
            raise ValueError(f"features.{key} contains unknown columns: {unknown}")
        return value

    include, exclude = names("include"), names("exclude")
    selected = list(raw if include is None else include)
    excluded = [name for name in raw if name not in selected or name in (exclude or [])]
    selected = [name for name in selected if name not in (exclude or [])]
    constant = []
    if options.get("drop_constant", False):
        constant = [name for name in selected if dataset[name].nunique(dropna=False) <= 1]
        selected = [name for name in selected if name not in constant]
    aliases = {}
    duplicate = []
    if options.get("drop_duplicate", False):
        canonical = []
        for name in selected:
            match = next((col for col in canonical if dataset[col].equals(dataset[name])), None)
            if match is None:
                canonical.append(name)
            else:
                aliases.setdefault(match, []).append(name)
                duplicate.append(name)
        selected = canonical
    if not selected:
        raise ValueError("Feature selection removed every feature")
    return {
        "input_features": selected,
        "dropped_features": {"excluded": excluded, "constant": constant, "duplicate": duplicate},
        "duplicate_feature_aliases": aliases,
    }


def apply_feature_schema(dataset, schema):
    """Select canonical raw columns, accepting consistent recorded aliases."""
    result = pd.DataFrame(index=dataset.index)
    missing = []
    for name in schema["input_features"]:
        sources = [col for col in [name] + schema["duplicate_feature_aliases"].get(name, [])
                   if col in dataset.columns]
        if not sources:
            missing.append(name)
            continue
        first = dataset[sources[0]]
        for source in sources[1:]:
            other = dataset[source]
            if not (first.eq(other) | (first.isna() & other.isna())).fillna(False).all():
                raise ValueError(f"Conflicting duplicate feature columns: {sources[0]}, {source}")
        result[name] = first
    if missing:
        raise ValueError(f"Missing required features: {missing}")
    return result


