{"file_path": "/app/src/utils/toc.ts", "content": "import {getPositions, MDAstTypes} from './mdast';

export interface TocOptions {
  listStyle?: string;
  bulletMarker?: string;
  orderedListStyle?: string;
  indentSize?: number;
  minLevel?: number;
  maxLevel?: number;
  title?: string;
  useExplicitIds?: boolean;
  stripFormattingInToc?: boolean;
  excludeHeadings?: string[];
}

const defaults: TocOptions = {
  listStyle: 'bullet', bulletMarker: '-', orderedListStyle: 'always-one',
  indentSize: 2, minLevel: 2, maxLevel: 6, title: '',
  useExplicitIds: false, stripFormattingInToc: false, excludeHeadings: [],
};

function displayText(text: string): string {
  return text.replace(/!\[\[[^\]]*\]\]/g, '')
      .replace(/!\[[^\]]*\]\([^)]*\)/g, '')
      .replace(/\[\[([^\]]+)\]\]/g, (_, target: string) => target.split('|').pop())
      .replace(/\[([^\]]+)\]\([^)]*\)/g, '$1');
}

function plainText(text: string): string {
  return displayText(text).replace(/<[^>]*>/g, '').replace(/[*_~\x60]/g, '').replace(/\\([\\\x60*{}\[\]()#+.!_>-])/g, '$1').trim();
}

/** Generate a table of contents only when an unprotected start marker exists. */
export function generateToc(text: string, suppliedOptions: TocOptions = {}): string {
  const options = {...defaults, ...suppliedOptions};
  const ranges = [MDAstTypes.Code, MDAstTypes.Math].flatMap((type) => getPositions(type, text).map((p) => [p.start.offset, p.end.offset]));
  const yaml = text.match(/^---[ \t]*\r?\n[\s\S]*?^---[ \t]*(?:\r?\n|$)/m);
  if (yaml && yaml.index === 0) ranges.push([0, yaml[0].length]);
  const protectedAt = (offset: number) => ranges.some(([start, end]) => offset >= start && offset < end);
  const marker = /<!--[ \t]*\/?[ \t]*toc[ \t]*-->/gi;
  let start: RegExpExecArray;
  let end: RegExpExecArray;
  for (const match of text.matchAll(marker)) {
    if (protectedAt(match.index)) continue;
    const isEnd = /^<!--[ \t]*\//.test(match[0]);
    if (!start && !isEnd) start = match;
    else if (start && isEnd) { end = match; break; }
  }
  if (!start) return text;
  const startEnd = start.index + start[0].length;
  const regionEnd = end ? end.index : startEnd;
  const newline = text.includes('\r\n') ? '\r\n' : '\n';
  const exclusions = (options.excludeHeadings || []).map((entry) => {
    if (entry.startsWith('/') && entry.endsWith('/') && entry.length > 1) {
      try { return new RegExp(entry.slice(1, -1), 'i'); } catch (_) { /* Treat invalid expressions as literals. */ }
    }
    return entry.toLowerCase();
  });
  const used = new Set<string>();
  const items: string[] = [];
  const headings = /^ {0,3}(#{1,6})(?:[ \t]+|$)([^\r\n]*)/gm;
  for (const match of text.matchAll(headings)) {
    if (protectedAt(match.index) || (match.index >= start.index && match.index < regionEnd)) continue;
    const level = match[1].length;
    if (level < Number(options.minLevel) || level > Number(options.maxLevel)) continue;
    let label = match[2].replace(/[ \t]+#+[ \t]*$/, '').trim();
    const explicit = label.match(/[ \t]+\{#([^\s}]+)\}[ \t]*$/);
    if (explicit) label = label.slice(0, explicit.index).trim();
    const plain = plainText(label);
    if (exclusions.some((entry) => typeof entry === 'string' ? entry === plain.toLowerCase() : entry.test(plain))) continue;
    const base = options.useExplicitIds && explicit ? explicit[1] : plain.toLowerCase().replace(/\s+/g, '-').replace(/[^a-z0-9_-]/g, '').replace(/-+/g, '-').replace(/^-|-$/g, '');
    let anchor = base;
    for (let suffix = 1; used.has(anchor); suffix++) anchor = base + '-' + suffix;
    used.add(anchor);
    const indicator = options.listStyle === 'number' ? (options.orderedListStyle === 'increment' ? items.length + 1 : 1) + '.' : options.bulletMarker;
    const indent = ' '.repeat(Math.max(0, (level - Number(options.minLevel)) * Number(options.indentSize)) || 0);
    items.push(indent + indicator + ' [' + (options.stripFormattingInToc ? plain : displayText(label)) + '](#' + anchor + ')');
  }
  const parts = [start[0], '', ...(options.title ? [options.title, ''] : []), ...items, '', end ? end[0] : '<!-- /toc -->'];
  const before = text.slice(0, start.index);
  const after = text.slice(end ? end.index + end[0].length : startEnd).replace(/^(?:[ \t]*\r?\n)*/, '');
  return before + parts.join(newline) + (after ? newline + newline + after : newline + newline);
}
"}

{"file_path": "/app/src/grid-layout.ts", "content": "import Yoga from 'yoga-layout';
import {type DOMElement, type DOMNode} from './dom.js';
import applyStyles from './styles.js';

type Track = {min: number; max: number; fr: number; auto: boolean};
type Item = {node: DOMNode; column: number; row: number; columns: number; rows: number};

const modified = new WeakSet<DOMNode>();

const parseTracks = (value?: string): Track[] => {
	const tokens = value?.match(/minmax\([^)]*\)|[^\s]+/g) ?? [];
	return tokens.map(token => {
		const match = /^minmax\(\s*(\d+(?:\.\d+)?)\s*,\s*(\d+(?:\.\d+)?)(fr)?\s*\)$/.exec(token);
		if (match) {
			return {min: Number(match[1]), max: match[3] ? Infinity : Number(match[2]), fr: match[3] ? Number(match[2]) : 0, auto: false};
		}

		if (token === 'auto') return {min: 0, max: Infinity, fr: 0, auto: true};
		if (/^\d+(?:\.\d+)?fr$/.test(token)) return {min: 0, max: Infinity, fr: Number.parseFloat(token), auto: false};
		const size = Number(token);
		return {min: Number.isFinite(size) && size >= 0 ? size : 0, max: Number.isFinite(size) && size >= 0 ? size : 0, fr: 0, auto: false};
	});
};

const placement = (value?: number | string): [number, number] | undefined => {
	if (value === undefined) return undefined;
	const match = /^\s*(\d+)\s*(?:\/\s*(\d+)\s*)?$/.exec(String(value));
	if (!match) return undefined;
	const start = Number(match[1]);
	const end = match[2] ? Number(match[2]) : start + 1;
	return start > 0 && end > start ? [start - 1, end - start] : undefined;
};

const restore = (node: DOMNode): void => {
	if (node.yogaNode && modified.has(node)) {
		applyStyles(node.yogaNode, {position: undefined, left: undefined, top: undefined, width: undefined, height: undefined, minWidth: undefined, minHeight: undefined, ...node.style});
		modified.delete(node);
	}

	if (node.nodeName !== '#text') for (const child of node.childNodes) restore(child);
};

const tracksFor = (tracks: Track[], count: number): Track[] => {
	while (tracks.length < count) tracks.push({min: 0, max: Infinity, fr: 0, auto: true});
	return tracks;
};

const sizeTracks = (tracks: Track[], items: Item[], axis: 'column' | 'row', available: number, gap: number): number[] => {
	const sizes = tracks.map(track => track.min);
	for (const item of items) {
		const index = axis === 'column' ? item.column : item.row;
		const span = axis === 'column' ? item.columns : item.rows;
		const yoga = item.node.yogaNode!;
		const intrinsic = axis === 'column' ? yoga.getComputedWidth() : yoga.getComputedHeight();
		const current = sizes.slice(index, index + span).reduce((a, b) => a + b, 0) + gap * (span - 1);
		const flexible = tracks.slice(index, index + span).map((track, offset) => ({track, index: index + offset})).filter(({track}) => track.auto);
		if (flexible.length > 0 && intrinsic > current) {
			for (const entry of flexible) sizes[entry.index] = (sizes[entry.index] ?? 0) + (intrinsic - current) / flexible.length;
		}
	}

	const remaining = Math.max(0, available - sizes.reduce((a, b) => a + b, 0) - gap * Math.max(0, tracks.length - 1));
	const totalFr = tracks.reduce((sum, track) => sum + track.fr, 0);
	if (totalFr > 0) for (const [index, track] of tracks.entries()) sizes[index] = (sizes[index] ?? 0) + remaining * track.fr / totalFr;
	return sizes;
};

const arrange = (node: DOMNode): void => {
	if (node.nodeName === '#text') return;
	for (const child of node.childNodes) arrange(child);
	if (node.style.display !== 'grid' || !node.yogaNode) return;
	const yoga = node.yogaNode;
	const columns = parseTracks(node.style.gridTemplateColumns);
	if (columns.length === 0) columns.push({min: 0, max: Infinity, fr: 0, auto: true});
	const rows = parseTracks(node.style.gridTemplateRows);
	const occupied = new Set<string>();
	const items: Item[] = [];
	const children = node.childNodes.filter(child => child.yogaNode && child.style.display !== 'none');
	// Reserve explicitly placed cells before auto-placement.
	const place = (child: DOMNode, explicitOnly: boolean): void => {
		const col = placement(child.style.gridColumn);
		const row = placement(child.style.gridRow);
		if (Boolean(col && row) !== explicitOnly) return;
		let x = col?.[0] ?? 0;
		let y = row?.[0] ?? 0;
		const width = col?.[1] ?? 1;
		const height = row?.[1] ?? 1;
		if (!explicitOnly) {
			for (let attempt = 0; attempt < 10000; attempt++) {
				let free = true;
				for (let dy = 0; dy < height; dy++) for (let dx = 0; dx < width; dx++) if (occupied.has(`${x + dx},${y + dy}`)) free = false;
				if (free && (col || x + width <= columns.length)) break;
				if (col) y++; else if (row) x++; else if (++x >= columns.length) {x = 0; y++;}
			}
		}

		for (let dy = 0; dy < height; dy++) for (let dx = 0; dx < width; dx++) occupied.add(`${x + dx},${y + dy}`);
		items.push({node: child, column: x, row: y, columns: width, rows: height});
	};
	for (const child of children) place(child, true);
	for (const child of children) place(child, false);
	tracksFor(columns, Math.max(columns.length, ...items.map(item => item.column + item.columns)));
	tracksFor(rows, Math.max(rows.length, ...items.map(item => item.row + item.rows)));
	const left = yoga.getComputedBorder(Yoga.EDGE_LEFT) + yoga.getComputedPadding(Yoga.EDGE_LEFT);
	const right = yoga.getComputedBorder(Yoga.EDGE_RIGHT) + yoga.getComputedPadding(Yoga.EDGE_RIGHT);
	const top = yoga.getComputedBorder(Yoga.EDGE_TOP) + yoga.getComputedPadding(Yoga.EDGE_TOP);
	const bottom = yoga.getComputedBorder(Yoga.EDGE_BOTTOM) + yoga.getComputedPadding(Yoga.EDGE_BOTTOM);
	const columnGap = node.style.columnGap ?? node.style.gap ?? 0;
	const rowGap = node.style.rowGap ?? node.style.gap ?? 0;
	const widths = sizeTracks(columns, items, 'column', Math.max(0, yoga.getComputedWidth() - left - right), columnGap);
	const heights = sizeTracks(rows, items, 'row', Math.max(0, yoga.getComputedHeight() - top - bottom), rowGap);
	const total = (sizes: number[], gap: number) => sizes.reduce((a, b) => a + b, 0) + Math.max(0, sizes.length - 1) * gap;
	yoga.setMinWidth(Math.max(typeof node.style.minWidth === 'number' ? node.style.minWidth : 0, total(widths, columnGap) + left + right));
	yoga.setMinHeight(Math.max(typeof node.style.minHeight === 'number' ? node.style.minHeight : 0, total(heights, rowGap) + top + bottom));
	modified.add(node);
	for (const item of items) {
		const child = item.node.yogaNode!;
		child.setPositionType(Yoga.POSITION_TYPE_ABSOLUTE);
		child.setPosition(Yoga.EDGE_LEFT, left + total(widths.slice(0, item.column), columnGap) + (item.column > 0 ? columnGap : 0));
		child.setPosition(Yoga.EDGE_TOP, top + total(heights.slice(0, item.row), rowGap) + (item.row > 0 ? rowGap : 0));
		if (item.node.style.width === undefined) child.setWidth(total(widths.slice(item.column, item.column + item.columns), columnGap));
		if (item.node.style.height === undefined) child.setHeight(total(heights.slice(item.row, item.row + item.rows), rowGap));
		modified.add(item.node);
	}
};

export default function calculateGridLayout(root: DOMElement): void {
	restore(root);
	root.yogaNode!.calculateLayout(undefined, undefined, Yoga.DIRECTION_LTR);
	// Repeat to propagate intrinsic grid sizes through flex ancestors and nested grids.
	for (let index = 0; index < 3; index++) {
		arrange(root);
		root.yogaNode!.calculateLayout(undefined, undefined, Yoga.DIRECTION_LTR);
	}
}
"}

{"file_path": "/app/igel/preprocessing.py", "old_string": "def update_dataset_props(dataset_props: dict, default_dataset_props: dict):", "new_string": "def fit_feature_schema(df, targets, options):
    """Capture the ordered raw inputs and their duplicate relationships."""
    if options is None:
        options = {}
    if not isinstance(options, dict):
        raise ValueError('dataset.features must be an object')
    raw = [column for column in df.columns if column not in targets]
    if len(set(df.columns)) != len(df.columns):
        raise ValueError('Duplicate column names in dataset')

    def names(key):
        value = options.get(key, [])
        if isinstance(value, str):
            value = [value]
        if not isinstance(value, list) or any(not isinstance(v, str) or not v.strip() for v in value):
            raise ValueError(f'features.{key} must contain non-empty column names')
        if len(set(value)) != len(value):
            raise ValueError(f'features.{key} contains duplicate entries')
        invalid = [v for v in value if v not in raw]
        if invalid:
            raise ValueError(f'Unknown or target columns in features.{key}: {invalid}')
        return value

    include = names('include') if 'include' in options else raw[:]
    excluded = names('exclude')
    selected = [name for name in include if name not in excluded]
    constant, duplicate, aliases = [], [], {}
    if options.get('drop_constant', False):
        constant = [name for name in selected if df[name].nunique(dropna=False) <= 1]
        selected = [name for name in selected if name not in constant]
    if options.get('drop_duplicate', False):
        canonical = []
        for name in selected:
            match = next ( (col for col in canonical if df[col].equals(df[name])), None)
            if match is None:
                canonical.append(name)
            else:
                duplicate.append(name)
                aliases.setdefault(match, []).append(name)
        selected = canonical
    if not selected:
        raise ValueError('Feature selection removed every feature')
    return {'input_features': selected, 'dropped_features': {'excluded': excluded, 'constant': constant, 'duplicate': duplicate}, 'duplicate_feature_aliases': aliases}


def apply_feature_schema(df, schema):
    """Align incoming raw columns, accepting consistent duplicate aliases."""
    result = {}
    missing = []
    for name in schema['input_features']:
        sources = [col for col in [name] + schema['duplicate_feature_aliases'].get(name, []) if col in df.columns]
        if not sources:
            missing.append(name)
            continue
        for other in sources[1:]:
            equal = df[sources[0]].eq(df[other]) | (df[sources[0]].isna() & df[other].isna())
            if not equal.fillna(False).all():
                raise ValueError(f'Conflicting duplicate feature columns: {sources[0]}, {other}')
        result[name] = df[sources[0]]
    if missing:
        raise ValueError(f'Missing required features: {missing}')
    return pd.DataFrame(result, index=df.index)


def update_dataset_props(dataset_props: dict, default_dataset_props: dict):"}

{"file_path": "/app/src/rules/auto-toc.ts", "content": "import {Options, RuleType} from '../rules';
import RuleBuilder, {BooleanOptionBuilder, DropdownOptionBuilder, ExampleBuilder, NumberOptionBuilder, OptionBuilderBase, TextAreaOptionBuilder, TextOptionBuilder} from './rule-builder';
import {generateToc, TocOptions} from '../utils/toc';

class AutoTocOptions implements Options, TocOptions {
  listStyle: string = 'bullet';
  bulletMarker: string = '-';
  orderedListStyle: string = 'always-one';
  indentSize: number = 2;
  minLevel: number = 2;
  maxLevel: number = 6;
  title: string = '';
  useExplicitIds: boolean = false;
  stripFormattingInToc: boolean = false;
  excludeHeadings: string[] = [];
}

@RuleBuilder.register
export default class AutoToc extends RuleBuilder<AutoTocOptions> {
  constructor() {
    super({nameKey: 'rules.auto-toc.name', descriptionKey: 'rules.auto-toc.description', type: RuleType.CONTENT});
  }

  get OptionsClass(): new () => AutoTocOptions { return AutoTocOptions; }

  apply(text: string, options: AutoTocOptions): string { return generateToc(text, options); }

  get exampleBuilders(): ExampleBuilder<AutoTocOptions>[] {
    return [new ExampleBuilder({
      description: 'Generate a table of contents between markers.',
      before: '<!-- toc -->\n\n<!-- /toc -->\n\n## Introduction',
      after: '<!-- toc -->\n\n- [Introduction](#introduction)\n\n<!-- /toc -->\n\n## Introduction',
    })];
  }

  get optionBuilders(): OptionBuilderBase<AutoTocOptions>[] {
    return [
      new DropdownOptionBuilder<AutoTocOptions, string>({OptionsClass: AutoTocOptions, nameKey: 'rules.auto-toc.list-style.name', descriptionKey: 'rules.auto-toc.list-style.description', optionsKey: 'listStyle', records: [{value: 'bullet', description: 'Bulleted list'}, {value: 'number', description: 'Numbered list'}]}),
      new DropdownOptionBuilder<AutoTocOptions, string>({OptionsClass: AutoTocOptions, nameKey: 'rules.auto-toc.bullet-marker.name', descriptionKey: 'rules.auto-toc.bullet-marker.description', optionsKey: 'bulletMarker', records: [{value: '-', description: 'Dash'}, {value: '*', description: 'Asterisk'}, {value: '+', description: 'Plus'}]}),
      new DropdownOptionBuilder<AutoTocOptions, string>({OptionsClass: AutoTocOptions, nameKey: 'rules.auto-toc.ordered-list-style.name', descriptionKey: 'rules.auto-toc.ordered-list-style.description', optionsKey: 'orderedListStyle', records: [{value: 'always-one', description: 'Always use 1'}, {value: 'increment', description: 'Increment each item'}]}),
