{"file_path": "/app/backend/providers/anthropic.ts", "content": "import Anthropic from "@anthropic-ai/sdk";
import type { AgentProvider, ProviderChatRequest, ProviderOptions, ProviderResponse } from "./types.ts";

export class AnthropicProvider implements AgentProvider {
  readonly id = "anthropic";
  readonly name = "Anthropic Claude";
  readonly type = "anthropic" as const;
  private client: Anthropic;

  constructor(apiKey: string) {
    this.client = new Anthropic({ apiKey });
  }

  supportsImages(): boolean { return true; }

  async *executeChat(request: ProviderChatRequest, options: ProviderOptions = {}): AsyncGenerator<ProviderResponse> {
    try {
      const userContent: Anthropic.ContentBlockParam[] = [{ type: "text", text: request.message }];
      for (const image of request.images || []) {
        if (image.type === "base64") {
          userContent.push({ type: "image", source: { type: "base64", media_type: image.mimeType as "image/png" | "image/jpeg" | "image/gif" | "image/webp", data: image.data } });
        }
      }
      const messages: Anthropic.MessageParam[] = [{ role: "user", content: userContent }];
      for (const entry of request.context || []) {
        let block: Anthropic.ContentBlockParam | undefined;
        try {
          const parsed = JSON.parse(entry.content);
          if (parsed.type === "tool_use" || parsed.type === "tool_result") block = parsed;
        } catch { /* Ordinary text context. */ }
        const role = entry.role === "assistant" ? "assistant" : "user";
        const last = messages[messages.length - 1];
        const content = block || { type: "text" as const, text: entry.content };
        if (last?.role === role && Array.isArray(last.content)) last.content.push(content);
        else messages.push({ role, content: [content] });
      }
      const stream = this.client.messages.stream({
        model: "claude-sonnet-4-20250514",
        max_tokens: options.maxTokens || 4000,
        temperature: options.temperature ?? 0.7,
        system: "You are Claude, a helpful AI assistant coordinating specialized agents. Use delegate_task to ask another agent to perform a task when appropriate.",
        messages,
        tools: [{ name: "delegate_task", description: "Delegate a task to another agent by its agent ID.", input_schema: { type: "object", properties: { agent_id: { type: "string" }, instructions: { type: "string" } }, required: ["agent_id", "instructions"] } }],
      }, { signal: options.abortController?.signal });
      for await (const event of stream) {
        if (event.type === "content_block_delta" && event.delta.type === "text_delta") {
          yield { type: "text", content: event.delta.text, metadata: { model: "claude-sonnet-4-20250514" } };
        }
      }
      const message = await stream.finalMessage();
      if (message.stop_reason === "tool_use") {
        for (const block of message.content) {
          if (block.type === "tool_use") yield { type: "tool_use", toolName: block.name, toolInput: block.input, toolUseId: block.id };
        }
      }
      yield { type: "done" };
    } catch (error) {
      yield { type: "error", error: error instanceof Error ? error.message : String(error) };
    }
  }
}
"}

