{"file_path": "/app/src/utils/toc.ts", "content": "import {getPositions, MDAstTypes} from './mdast';
import {yamlRegex} from './regex';

export interface TocOptions {
  listStyle?: 'bullet' | 'number';
  bulletMarker?: string;
  orderedListStyle?: 'always-one' | 'increment';
  indentSize?: number;
  minLevel?: number;
  maxLevel?: number;
  title?: string;
  useExplicitIds?: boolean;
  stripFormattingInToc?: boolean;
  excludeHeadings?: string[];
}

function displayText(text: string): string {
  return text.replace(/!\[\[[^\]]*\]\]/g, '')
      .replace(/!\[[^\]]*\]\([^)]*\)/g, '')
      .replace(/\[\[([^\]]+)\]\]/g, (_match, content: string) => content.split('|').pop())
      .replace(/\[([^\]]+)\]\([^)]*\)/g, '$1');
}

function stripFormatting(text: string): string {
  return text.replace(/<[^>]*>/g, '').replace(/[*_`~]/g, '').replace(/\\([\\`*{}\[\]()#+.!_>~-])/g, '$1');
}

/** Generate the opted-in table of contents without changing unrelated document content. */
export function generateToc(text: string, options: TocOptions = {}): string {
  const settings = {
    listStyle: 'bullet', bulletMarker: '-', orderedListStyle: 'always-one',
    indentSize: 2, minLevel: 2, maxLevel: 6, title: '',
    useExplicitIds: false, stripFormattingInToc: false, excludeHeadings: [],
    ...options,
  };
  const ranges = [...getPositions(MDAstTypes.Code, text), ...getPositions(MDAstTypes.Math, text)]
      .map((position) => [position.start.offset, position.end.offset]);
  const yaml = text.match(yamlRegex);
  if (yaml) ranges.push([0, yaml[0].length]);
  const protectedAt = (offset: number) => ranges.some(([start, end]) => offset >= start && offset < end);

  const marker = /<!--[ \t]*\/?[ \t]*toc[ \t]*-->/gi;
  let start: RegExpExecArray;
  let end: RegExpExecArray;
  let match: RegExpExecArray;
  while ((match = marker.exec(text))) {
    if (protectedAt(match.index)) continue;
    if (!start && !/^<!--[ \t]*\//.test(match[0])) start = match;
    else if (start && /^<!--[ \t]*\//.test(match[0])) {
      end = match;
      break;
    }
  }
  if (!start) return text;
  const regionStart = start.index + start[0].length;
  const regionEnd = end ? end.index : regionStart;
  const exclusions = settings.excludeHeadings.map((entry) => {
    if (entry.startsWith('/') && entry.endsWith('/') && entry.length > 1) {
      try {
        return new RegExp(entry.slice(1, -1), 'i');
      } catch (_) {
        return null;
      }
    }
    return entry.toLowerCase();
  });
  const used = new Set<string>();
  const items: string[] = [];
  const heading = /^ {0,3}(#{1,6})[ \t]+([^\r\n]*?)\s*$/gm;
  while ((match = heading.exec(text))) {
    if (protectedAt(match.index) || (match.index >= start.index && match.index < regionEnd)) continue;
    const level = match[1].length;
    if (level < Number(settings.minLevel) || level > Number(settings.maxLevel)) continue;
    let label = match[2].replace(/[ \t]+#+[ \t]*$/, '').trim();
    const id = label.match(/[ \t]+\{#([^}]+)\}[ \t]*$/);
    if (id) label = label.slice(0, id.index).trim();
    const resolved = displayText(label).trim();
    const plain = stripFormatting(resolved).trim();
    if (exclusions.some((entry) => typeof entry === 'string' ? entry === plain.toLowerCase() : entry && entry.test(plain))) continue;
    const base = settings.useExplicitIds && id ? id[1] : plain.toLowerCase().replace(/\s+/g, '-').replace(/[^a-z0-9_-]/g, '').replace(/-+/g, '-').replace(/^-|-$/g, '');
    let anchor = base;
    let suffix = 1;
    while (used.has(anchor)) anchor = base + '-' + suffix++;
    used.add(anchor);
    const indent = ' '.repeat(Math.max(0, (level - Number(settings.minLevel)) * Number(settings.indentSize)) || 0);
    const bullet = settings.listStyle === 'number' ? (settings.orderedListStyle === 'increment' ? items.length + 1 : 1) + '.' : settings.bulletMarker;
    items.push(indent + bullet + ' [' + (settings.stripFormattingInToc ? plain : resolved) + '](#' + anchor + ')');
  }
  const newline = text.includes('\r\n') ? '\r\n' : '\n';
  const body = [settings.title, items.join(newline)].filter(Boolean).join(newline + newline);
  const closing = end ? end[0] : '<!-- /toc -->';
  let after = text.slice(end ? end.index + end[0].length : regionStart);
  after = after.replace(/^(?:[ \t]*\r?\n)*/, '');
  return text.slice(0, regionStart) + newline + newline + (body ? body + newline + newline : '') + closing + newline + newline + after;
}
"}

{"file_path": "/app/src/rules/auto-toc.ts", "content": "import {Options, RuleType} from '../rules';
import {generateToc, TocOptions} from '../utils/toc';
import RuleBuilder, {BooleanOptionBuilder, DropdownOptionBuilder, ExampleBuilder, NumberOptionBuilder, OptionBuilderBase, TextAreaOptionBuilder, TextOptionBuilder} from './rule-builder';

class AutoTocOptions implements Options, TocOptions {
  listStyle: 'bullet' | 'number' = 'bullet';
  bulletMarker = '-';
  orderedListStyle: 'always-one' | 'increment' = 'always-one';
  indentSize = 2;
  minLevel = 2;
  maxLevel = 6;
  title = '';
  useExplicitIds = false;
  stripFormattingInToc = false;
  excludeHeadings: string[] = [];
}

@RuleBuilder.register
export default class AutoToc extends RuleBuilder<AutoTocOptions> {
  constructor() {
    super({nameKey: 'rules.auto-toc.name', descriptionKey: 'rules.auto-toc.description', type: RuleType.CONTENT});
  }

  get OptionsClass(): new () => AutoTocOptions {
    return AutoTocOptions;
  }

  apply(text: string, options: AutoTocOptions): string {
    return generateToc(text, options);
  }

  get exampleBuilders(): ExampleBuilder<AutoTocOptions>[] {
    return [new ExampleBuilder({
      description: 'Generate a table of contents at the marker.',
      before: '<!-- toc -->\n\n## First',
      after: '<!-- toc -->\n\n- [First](#first)\n\n<!-- /toc -->\n\n## First',
    })];
  }

  get optionBuilders(): OptionBuilderBase<AutoTocOptions>[] {
    return [
      new DropdownOptionBuilder<AutoTocOptions, 'bullet' | 'number'>({
        OptionsClass: AutoTocOptions, nameKey: 'rules.auto-toc.list-style.name', descriptionKey: 'rules.auto-toc.list-style.description', optionsKey: 'listStyle',
        records: [{value: 'bullet', description: 'Use bullets'}, {value: 'number', description: 'Use numbers'}],
      }),
      new TextOptionBuilder({OptionsClass: AutoTocOptions, nameKey: 'rules.auto-toc.bullet-marker.name', descriptionKey: 'rules.auto-toc.bullet-marker.description', optionsKey: 'bulletMarker'}),
      new DropdownOptionBuilder<AutoTocOptions, 'always-one' | 'increment'>({
        OptionsClass: AutoTocOptions, nameKey: 'rules.auto-toc.ordered-list-style.name', descriptionKey: 'rules.auto-toc.ordered-list-style.description', optionsKey: 'orderedListStyle',
        records: [{value: 'always-one', description: 'Use 1 for every item'}, {value: 'increment', description: 'Increment every item'}],
      }),
      new NumberOptionBuilder({OptionsClass: AutoTocOptions, nameKey: 'rules.auto-toc.indent-size.name', descriptionKey: 'rules.auto-toc.indent-size.description', optionsKey: 'indentSize'}),
      new NumberOptionBuilder({OptionsClass: AutoTocOptions, nameKey: 'rules.auto-toc.min-level.name', descriptionKey: 'rules.auto-toc.min-level.description', optionsKey: 'minLevel'}),
      new NumberOptionBuilder({OptionsClass: AutoTocOptions, nameKey: 'rules.auto-toc.max-level.name', descriptionKey: 'rules.auto-toc.max-level.description', optionsKey: 'maxLevel'}),
      new TextOptionBuilder({OptionsClass: AutoTocOptions, nameKey: 'rules.auto-toc.title.name', descriptionKey: 'rules.auto-toc.title.description', optionsKey: 'title'}),
      new BooleanOptionBuilder({OptionsClass: AutoTocOptions, nameKey: 'rules.auto-toc.use-explicit-ids.name', descriptionKey: 'rules.auto-toc.use-explicit-ids.description', optionsKey: 'useExplicitIds'}),
      new BooleanOptionBuilder({OptionsClass: AutoTocOptions, nameKey: 'rules.auto-toc.strip-formatting-in-toc.name', descriptionKey: 'rules.auto-toc.strip-formatting-in-toc.description', optionsKey: 'stripFormattingInToc'}),
      new TextAreaOptionBuilder({OptionsClass: AutoTocOptions, nameKey: 'rules.auto-toc.exclude-headings.name', descriptionKey: 'rules.auto-toc.exclude-headings.description', optionsKey: 'excludeHeadings'}),
    ];
  }
}
"}

