from pathlib import Path
import pandas as pd
root = Path(tempfile.mkdtemp(prefix='igel-check-'))
os.chdir(root)
from igel import Igel
from igel.feature_schema import FeatureSchemaError
from igel.servers.fastapi_server import predict
from fastapi import HTTPException
from igel.constants import Constants

def write(df, path): pd.DataFrame(df).to_csv(path, index=False)

def run(model, targets):
    data = {'a':[1,2,3,4,5,6], 'b':[2,4,6,8,10,12], 'dup':[1,2,3,4,5,6], 'constant':[1]*6, 'other':[5,6,7,8,9,10]}
    if targets:
        data.update({'y':[2,4,6,8,10,12], 'z':[3,6,9,12,15,18]})
    write(data, 'train.csv')
    config = {'dataset':{'features':{'include':['b','dup','a','constant','other'], 'exclude':'other', 'drop_constant':True, 'drop_duplicate':True}}, 'model':model}
    if targets: config['target'] = targets
    Path('config.json').write_text(json.dumps(config))
    Igel(cmd='fit', data_path='train.csv', yaml_path='config.json')
    desc = json.loads(Path('model_results/description.json').read_text())
    assert desc['input_features'] == ['b','dup'], desc
    assert desc['dropped_features'] == {'excluded':['other'], 'constant':['constant'], 'duplicate':['a']}
    assert desc['duplicate_feature_aliases'] == {'dup':['a']}
    write({'extra':[99,99], 'a':[7,8], 'b':[14,16]}, 'predict.csv')
    pred = Igel(cmd='predict', data_path='predict.csv')
    assert len(pred.predictions)==2
    write({'a':[7,8], 'dup':[7,9], 'b':[14,16]}, 'bad.csv')
    try: Igel(cmd='predict', data_path='bad.csv')
    except FeatureSchemaError as e: assert 'dup' in str(e) and 'a' in str(e)
    else: raise AssertionError('conflict not rejected')
