def parse_ddl_table(lines: List[Line]) -> Optional[DdlTable]:
    text = "".join(n.token.prefix + n.token.token for line in lines for n in line.nodes)
    parts = _parts(text)
    if not parts:
        return None
    _, name, items, _ = parts
    columns = []
    constraints = []
    for item in items:
        match = _CONSTRAINT.match(item)
        if match:
            constraints.append(DdlTableConstraint(re.sub(r"\\s+", " ", match.group().lower())))
        elif item:
            columns.append(_column(item))
    return DdlTable(name, columns, constraints)


def _format_expression(text: str, type_end: int = 0) -> str:
    tokens = list(_TOKEN.finditer(text))
    result = ""
    previous = ""
    keywords = {"not", "null", "default", "references", "constraint", "check", "primary", "foreign", "key", "unique", "on", "delete", "update", "cascade", "set", "as", "generated", "always", "stored", "true", "false", "and", "or", "in", "is", "partition", "by", "cluster", "options"}
